BVHBuildNode *BVHAggregate::buildRecursive(
        ThreadLocal<Allocator> &threadAllocators,
        pstd::span<BVHPrimitive> bvhPrimitives,
        std::atomic<int> *totalNodes, std::atomic<int> *orderedPrimsOffset,
        std::vector<Primitive> &orderedPrims) {
    Allocator alloc = threadAllocators.Get();
    BVHBuildNode *node = alloc.new_object<BVHBuildNode>();
    <<Initialize BVHBuildNode for primitive range>>        ++*totalNodes;
       <<Compute bounds of all primitives in BVH node>>           Bounds3f bounds;
          for (const auto &prim : bvhPrimitives)
              bounds = Union(bounds, prim.bounds);
       if (bounds.SurfaceArea() == 0 || bvhPrimitives.size() == 1) {
           <<Create leaf BVHBuildNode>>               int firstPrimOffset = orderedPrimsOffset->fetch_add(bvhPrimitives.size());
              for (size_t i = 0; i < bvhPrimitives.size(); ++i) {
                  int index = bvhPrimitives[i].primitiveIndex;
                  orderedPrims[firstPrimOffset + i] = primitives[index];
              }
              node->InitLeaf(firstPrimOffset, bvhPrimitives.size(), bounds);
              return node;
       } else {
           <<Compute bound of primitive centroids and choose split dimension dim>>               Bounds3f centroidBounds;
              for (const auto &prim : bvhPrimitives)
                  centroidBounds = Union(centroidBounds, prim.Centroid());
              int dim = centroidBounds.MaxDimension();
           <<Partition primitives into two sets and build children>>               if (centroidBounds.pMax[dim] == centroidBounds.pMin[dim]) {
                  <<Create leaf BVHBuildNode>>                      int firstPrimOffset = orderedPrimsOffset->fetch_add(bvhPrimitives.size());
                     for (size_t i = 0; i < bvhPrimitives.size(); ++i) {
                         int index = bvhPrimitives[i].primitiveIndex;
                         orderedPrims[firstPrimOffset + i] = primitives[index];
                     }
                     node->InitLeaf(firstPrimOffset, bvhPrimitives.size(), bounds);
                     return node;
              } else {
                  int mid = bvhPrimitives.size() / 2;
                  <<Partition primitives based on splitMethod>>                      switch (splitMethod) {
                     case SplitMethod::Middle: {
                         <<Partition primitives through node’s midpoint>>                             Float pmid = (centroidBounds.pMin[dim] + centroidBounds.pMax[dim]) / 2;
                            auto midIter =
                                std::partition(bvhPrimitives.begin(), bvhPrimitives.end(),
                                    [dim, pmid](const BVHPrimitive &pi) {
                                        return pi.Centroid()[dim] < pmid;
                                    });
                            mid = midIter - bvhPrimitives.begin();
                            if (midIter != bvhPrimitives.begin() && midIter != bvhPrimitives.end())
                                break;
                     }
                     case SplitMethod::EqualCounts: {
                         <<Partition primitives into equally sized subsets>>                             mid = bvhPrimitives.size() / 2;
                            std::nth_element(bvhPrimitives.begin(), bvhPrimitives.begin() + mid, 
                                             bvhPrimitives.end(),
                                [dim](const BVHPrimitive &a, const BVHPrimitive &b) { 
                                    return a.Centroid()[dim] < b.Centroid()[dim];
                                });
                         break;
                     }
                     case SplitMethod::SAH:
                     default: {
                         <<Partition primitives using approximate SAH>>                             if (bvhPrimitives.size() <= 2) {
                                <<Partition primitives into equally sized subsets>>                                    mid = bvhPrimitives.size() / 2;
                                   std::nth_element(bvhPrimitives.begin(), bvhPrimitives.begin() + mid, 
                                                    bvhPrimitives.end(),
                                       [dim](const BVHPrimitive &a, const BVHPrimitive &b) { 
                                           return a.Centroid()[dim] < b.Centroid()[dim];
                                       });
                            } else {
                                <<Allocate BVHSplitBucket for SAH partition buckets>>                                    constexpr int nBuckets = 12;
                                   BVHSplitBucket buckets[nBuckets];
                                <<Initialize BVHSplitBucket for SAH partition buckets>>                                    for (const auto &prim : bvhPrimitives) {
                                       int b = nBuckets * centroidBounds.Offset(prim.Centroid())[dim];
                                       if (b == nBuckets) b = nBuckets - 1;
                                       buckets[b].count++;
                                       buckets[b].bounds = Union(buckets[b].bounds, prim.bounds);
                                   }
                                <<Compute costs for splitting after each bucket>>                                    constexpr int nSplits = nBuckets - 1;
                                   Float costs[nSplits] = {};
                                   <<Partially initialize costs using a forward scan over splits>>                                       int countBelow = 0;
                                      Bounds3f boundBelow;
                                      for (int i = 0; i < nSplits; ++i) {
                                          boundBelow = Union(boundBelow, buckets[i].bounds);
                                          countBelow += buckets[i].count;
                                          costs[i] += countBelow * boundBelow.SurfaceArea();
                                      }
                                   <<Finish initializing costs using a backward scan over splits>>                                       int countAbove = 0;
                                      Bounds3f boundAbove;
                                      for (int i = nSplits; i >= 1; --i) {
                                          boundAbove = Union(boundAbove, buckets[i].bounds);
                                          countAbove += buckets[i].count;
                                          costs[i - 1] += countAbove * boundAbove.SurfaceArea();
                                      }
                                <<Find bucket to split at that minimizes SAH metric>>                                    int minCostSplitBucket = -1;
                                   Float minCost = Infinity;
                                   for (int i = 0; i < nSplits; ++i) {
                                       <<Compute cost for candidate split and update minimum if necessary>>                                           if (costs[i] < minCost) {
                                              minCost = costs[i];
                                              minCostSplitBucket = i;
                                          }
                                   }
                                   <<Compute leaf cost and SAH split cost for chosen split>>                                       Float leafCost = bvhPrimitives.size();
                                      minCost = 1.f / 2.f + minCost / bounds.SurfaceArea();
                                <<Either create leaf or split primitives at selected SAH bucket>>                                    if (bvhPrimitives.size() > maxPrimsInNode || minCost < leafCost) {
                                       auto midIter = std::partition(bvhPrimitives.begin(),
                                           bvhPrimitives.end(),
                                           [=](const BVHPrimitive &bp) {
                                               int b = nBuckets * centroidBounds.Offset(bp.Centroid())[dim];
                                               if (b == nBuckets) b = nBuckets - 1;
                                               return b <= minCostSplitBucket;
                                           });
                                       mid = midIter - bvhPrimitives.begin();
                                   } else {
                                       <<Create leaf BVHBuildNode>>                                           int firstPrimOffset = orderedPrimsOffset->fetch_add(bvhPrimitives.size());
                                          for (size_t i = 0; i < bvhPrimitives.size(); ++i) {
                                              int index = bvhPrimitives[i].primitiveIndex;
                                              orderedPrims[firstPrimOffset + i] = primitives[index];
                                          }
                                          node->InitLeaf(firstPrimOffset, bvhPrimitives.size(), bounds);
                                          return node;
                                   }
                            }
                         break;
                     }
                     }
                  BVHBuildNode *children[2];
                  <<Recursively build BVHs for children>>                      if (bvhPrimitives.size() > 128 * 1024) {
                         <<Recursively build child BVHs in parallel>>                             ParallelFor(0, 2, [&](int i) {
                                if (i == 0)
                                    children[0] =
                                        buildRecursive(threadAllocators, bvhPrimitives.subspan(0, mid),
                                                       totalNodes, orderedPrimsOffset, orderedPrims);
                                else
                                    children[1] =
                                        buildRecursive(threadAllocators, bvhPrimitives.subspan(mid),
                                                       totalNodes, orderedPrimsOffset, orderedPrims);
                            });
                     } else {
                         <<Recursively build child BVHs sequentially>>                             children[0] =
                                buildRecursive(threadAllocators, bvhPrimitives.subspan(0, mid),
                                               totalNodes, orderedPrimsOffset, orderedPrims);
                            children[1] =
                                buildRecursive(threadAllocators, bvhPrimitives.subspan(mid),
                                               totalNodes, orderedPrimsOffset, orderedPrims);
                     }
                  node->InitInterior(dim, children[0], children[1]);
              }
       }
    return node;
}

