static void RadixSort(std::vector<MortonPrimitive> *v) {
    std::vector<MortonPrimitive> tempVector(v->size());
    constexpr int bitsPerPass = 6;
    constexpr int nBits = 30;
    constexpr int nPasses = nBits / bitsPerPass;
    for (int pass = 0; pass < nPasses; ++pass) {
        <<Perform one pass of radix sort, sorting bitsPerPass bits>>            int lowBit = pass * bitsPerPass;
           <<Set in and out vector references for radix sort pass>>               std::vector<MortonPrimitive> &in = (pass & 1) ? tempVector : *v;
              std::vector<MortonPrimitive> &out = (pass & 1) ? *v : tempVector;
           <<Count number of zero bits in array for current radix sort bit>>               constexpr int nBuckets = 1 << bitsPerPass;
              int bucketCount[nBuckets] = { 0 };
              constexpr int bitMask = (1 << bitsPerPass) - 1;
              for (const MortonPrimitive &mp : in) {
                  int bucket = (mp.mortonCode >> lowBit) & bitMask;
                  ++bucketCount[bucket];
              }
           <<Compute starting index in output array for each bucket>>               int outIndex[nBuckets];
              outIndex[0] = 0;
              for (int i = 1; i < nBuckets; ++i)
